"""ISO-8601 durations: parsing, calendar addition and canonical output.

See task.md. `Duration` and `DurationError` are part of the contract: keep their
names, fields and field order as they are.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import datetime, timedelta
from fractions import Fraction


class DurationError(ValueError):
    """Raised for text that is not a well-formed ISO-8601 duration."""


@dataclass(frozen=True)
class Duration:
    """A duration. Every component is non-negative; `negative` signs the whole."""

    years: int = 0
    months: int = 0
    days: int = 0
    hours: int = 0
    minutes: int = 0
    seconds: int = 0
    microseconds: int = 0
    negative: bool = False


_NUM = r"([0-9]+(?:[.,][0-9]+)?)"
_PATTERN = re.compile(
    rf"(-)?P(?:{_NUM}W|(?:{_NUM}Y)?(?:{_NUM}M)?(?:{_NUM}D)?"
    rf"(T(?:{_NUM}H)?(?:{_NUM}M)?(?:{_NUM}S)?)?)",
    re.ASCII,
)

_US = {"S": 1_000_000, "M": 60_000_000, "H": 3_600_000_000}
_DAY_US = 86_400_000_000
# (field, unit in microseconds) from largest to smallest cascade target
_CASCADE = (
    ("days", _DAY_US),
    ("hours", _US["H"]),
    ("minutes", _US["M"]),
    ("seconds", _US["S"]),
    ("microseconds", 1),
)
_UNIT_US = {
    "W": 7 * _DAY_US,
    "D": _DAY_US,
    "H": _US["H"],
    "M": _US["M"],
    "S": _US["S"],
}


def _split(num: str) -> tuple[int, Fraction]:
    ip, sep, fp = num.replace(",", ".").partition(".")
    frac = Fraction(int(fp), 10 ** len(fp)) if sep else Fraction(0)
    return int(ip), frac


def parse(text: str) -> Duration:
    """Parse an ISO-8601 duration."""
    m = _PATTERN.fullmatch(text)
    if m is None:
        raise DurationError(f"invalid duration: {text!r}")
    sign, weeks, years, months, days, tpart, hours, minutes, seconds = m.groups()
    if weeks is None and not any((years, months, days, hours, minutes, seconds)):
        raise DurationError(f"no components in duration: {text!r}")
    if tpart is not None and not any((hours, minutes, seconds)):
        raise DurationError(f"'T' without time components: {text!r}")

    items = [
        ("Y", years), ("M", months), ("W", weeks), ("D", days),
        ("H", hours), ("m", minutes), ("S", seconds),
    ]
    present = [(k, v) for k, v in items if v is not None]
    values: dict[str, int] = {
        "years": 0, "months": 0, "days": 0, "hours": 0,
        "minutes": 0, "seconds": 0, "microseconds": 0,
    }
    names = {
        "Y": "years", "M": "months", "W": "days", "D": "days",
        "H": "hours", "m": "minutes", "S": "seconds",
    }
    for idx, (key, num) in enumerate(present):
        whole, frac = _split(num)
        if key == "W":
            whole *= 7
        values[names[key]] += whole
        if frac:
            if idx != len(present) - 1 or key in ("Y", "M"):
                raise DurationError(f"invalid fraction in duration: {text!r}")
            rest = int(frac * _UNIT_US[key if key != "m" else "M"])
            for field, unit in _CASCADE:
                q, rest = divmod(rest, unit)
                values[field] += q
        elif "." in num or "," in num:
            if idx != len(present) - 1 or key in ("Y", "M"):
                raise DurationError(f"invalid fraction in duration: {text!r}")

    negative = sign is not None and any(values.values())
    return Duration(negative=negative, **values)


def _days_in_month(year: int, month: int) -> int:
    if month == 2:
        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
        return 29 if leap else 28
    return 30 if month in (4, 6, 9, 11) else 31


def add(start: datetime, duration: Duration) -> datetime:
    """Return `start` shifted by `duration`, calendar-correct."""
    sign = -1 if duration.negative else 1
    shift = sign * (12 * duration.years + duration.months)
    year, month0 = divmod(start.year * 12 + (start.month - 1) + shift, 12)
    if not 1 <= year <= 9999:
        raise ValueError("resulting year out of range")
    month = month0 + 1
    day = min(start.day, _days_in_month(year, month))
    result = start.replace(year=year, month=month, day=day)
    try:
        return result + sign * timedelta(
            days=duration.days,
            hours=duration.hours,
            minutes=duration.minutes,
            seconds=duration.seconds,
            microseconds=duration.microseconds,
        )
    except OverflowError as exc:
        raise ValueError("resulting datetime out of range") from exc


def format(duration: Duration) -> str:  # noqa: A001 - the contract names it this
    """Return the canonical ISO-8601 text for `duration`."""
    d = duration
    if not any((d.years, d.months, d.days, d.hours, d.minutes, d.seconds, d.microseconds)):
        return "PT0S"
    out = "-P" if d.negative else "P"
    for value, designator in ((d.years, "Y"), (d.months, "M"), (d.days, "D")):
        if value:
            out += f"{value}{designator}"
    time = ""
    if d.hours:
        time += f"{d.hours}H"
    if d.minutes:
        time += f"{d.minutes}M"
    if d.seconds or d.microseconds:
        time += str(d.seconds)
        if d.microseconds:
            time += "." + f"{d.microseconds:06d}".rstrip("0")
        time += "S"
    if time:
        out += "T" + time
    return out
